// Writes app/swap/swapKitSecrets.ts from the SWAPKIT_API_KEY environment
// variable.
//
//   node scripts/generate-swapkit-secrets.js
//
// The generated file is gitignored; app/swap/swapKitSecrets.copy.ts is the
// committed template it shadows. Behaviour by env-var presence:
//
//   - set                      overwrite with the real key.
//   - unset, file exists       preserve, so a developer refreshing the tree
//                              with no env var set keeps a working key.
//   - unset, file missing      write the placeholder so TypeScript compiles
//                              and Jest runs. SwapKitClient's constructor
//                              throws on the placeholder, so a build that
//                              shipped without the secret fails at the first
//                              swap. This is the external-fork PR case.
//
// The key is injected as a JSON string, which survives quotes, backslashes,
// and anything else an API key may contain.

const fs = require('fs');
const path = require('path');

const PLACEHOLDER = 'replace-me-with-real-key';
const OUT = path.join(__dirname, '..', 'app', 'swap', 'swapKitSecrets.ts');

const envKey = process.env.SWAPKIT_API_KEY;
if (!envKey && fs.existsSync(OUT)) {
  console.log(
    `generate-swapkit-secrets: SWAPKIT_API_KEY unset, preserving ${OUT}`,
  );
  process.exit(0);
}

const key = envKey || PLACEHOLDER;
const banner =
  '// Generated by scripts/generate-swapkit-secrets.js. Do not commit.';
fs.writeFileSync(
  OUT,
  `${banner}\nexport const SWAPKIT_API_KEY = ${JSON.stringify(key)};\n`,
);

console.log(
  envKey
    ? 'generate-swapkit-secrets: wrote the key from SWAPKIT_API_KEY'
    : 'generate-swapkit-secrets: wrote the placeholder; swap execution will refuse it',
);
